import pandas as pd
import numpy as np


def task_func(column, data):
    """
    Analyzes a list of stock data and calculates the sum, mean, minimum, and maximum
    values for a specified column.

    Parameters:
    - column (str): The name of the column to analyze. Valid options are 'Date', 'Open', 'High',
                    'Low', 'Close', and 'Volume'.
    - data (list of lists): A list where each element is a list representing stock data for a single day.
                            Each inner list should contain values in the following order:
                            'Date', 'Open', 'High', 'Low', 'Close', 'Volume'.
    Returns:
    - dict: A dictionary containing the calculated 'sum', 'mean', 'min' (minimum), and 'max' (maximum)
            for the specified column. If the input data is empty, 'sum' will be 0, and 'mean', 'min', and
            'max' will be NaN.

    Requirements:
    - pandas
    - numpy

    Raises:
    - ValueError: If the specified column name is not valid.

    Example:
    >>> data = [[datetime(2022, 1, 1), 100, 105, 95, 102, 10000]]
    >>> results = task_func('Open', data)
    >>> results
    {'sum': 100, 'mean': 100.0, 'min': 100, 'max': 100}
    >>> type(results)
    <class 'dict'>
    """
def task_func(column, data):
    if column not in ['Date', 'Open', 'High', 'Low', 'Close', 'Volume']:
            raise ValueError("Invalid column name. Valid options are 'Date', 'Open', 'High', 'Low', 'Close', and 'Volume'.")

        if not data:
            return {'sum': 0, 'mean': np.nan, 'min': np.nan, 'max': np.nan}

        if column == 'Date':
            return {'sum': 0, 'mean': np.nan, 'min': np.nan, 'max': np.nan}

        if column == 'Open':
            return {'sum': sum([row[1] for row in data]), 'mean': np.mean([row[1] for row in data]), 'min': min([row[1] for row in data]), 'max': max([row[1] for row in data])}

        if column == 'High':
            return {'sum': sum([row[2] for row in data]), 'mean': np.mean([row[2] for row in data]), 'min': min([row[2] for row in data]), 'max': max([row[2] for row in data])}

        if column == 'Low':
            return {'sum': sum([row[3] for row in data]), 'mean': np.mean([row[3] for row in data]), 'min': min([row[3] for row in data]), 'max': max([row[3] for row in data])}

        if column == 'Close':
            return {'sum': sum([row[4] for row in data]), 'mean': np.mean([row[4] for row in data]), 'min': min([row[4] for row in data]), 'max': max([row[4] for row in data])}

        if column == 'Volume':
            return {'sum': sum([row[5] for row in data]), 'mean': np.mean([row[5] for row in data]), 'min': min([row[5] for row in data]), 'max': max([row[5] for row in data])}

